<script setup lang="ts">
import { reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { platformApi } from '../api'
const router=useRouter();const loading=ref(false);const showPassword=ref(false);const error=ref('');const form=reactive({login_name:'platform',password:''})
async function login(){loading.value=true;error.value='';try{const result=await platformApi<{access_token:string;admin?:{role?:string}}>('/auth/login',{method:'POST',body:JSON.stringify(form)});localStorage.setItem('clothp_platform_access_token',result.access_token);localStorage.setItem('clothp_platform_role',result.admin?.role||'assistant');await router.push('/platform/tenants')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
</script>
<template><div class="login-page"><section class="login-hero"><div class="login-logo">一智算 · 平台控制面</div><div><h1>租户运营与<br>平台参数统一管理</h1><p>平台管理员使用独立身份。这里不提供租户业务数据入口，也不存在可管理所有业务的超级租户。</p></div><div class="login-features"><span>✓ 独立平台会话</span><span>✓ 租户生命周期</span><span>✓ 操作审计</span></div></section><section class="login-form-wrap"><form class="login-form" @submit.prevent="login"><h2>平台管理员登录</h2><p class="text-muted">该账号不属于任何租户</p><div v-if="error" class="notice error" style="margin-top:20px">{{error}}</div><div class="field"><label class="required">平台账号</label><input v-model.trim="form.login_name" autocomplete="username"></div><div class="field"><label class="required">密码</label><div class="password-input"><input v-model="form.password" :type="showPassword ? 'text' : 'password'" autocomplete="current-password"><button type="button" class="password-toggle" :aria-label="showPassword ? '隐藏密码' : '显示密码'" @click="showPassword = !showPassword">{{showPassword?'隐藏':'显示'}}</button></div></div><button class="button" :disabled="loading">{{loading?'正在登录…':'登 录'}}</button><p style="margin-top:20px"><RouterLink to="/login" class="button link">返回租户登录</RouterLink></p></form></section></div></template>
